class Menu;
class MenuSystem;
enum MenuColor { MENUCOLOR_NORMAL };

class MenuEntry
{
  unsigned int flags;
public:
  virtual ~MenuEntry() {}
  virtual MenuColor GetColor();
  virtual void Show();
  virtual void Hide();
  virtual void Enable();
  virtual void Disable();
  virtual void Activate();
  virtual void Deactivate();
  virtual void OnTick(float) {}
  virtual void OnMenuOpen(Menu*, MenuSystem*);
  virtual void OnMenuClose();
  virtual void OnButtonPress(int) {}
  virtual void OnButtonRelease(int) {}
protected:
  virtual void OnHide() {}
  virtual void OnShow() {}
  virtual void OnEnable() {}
  virtual void OnDisable() {}
  virtual void OnActivate() {}
  virtual void OnDeactivate() {}
public:
  virtual int MenuText(char *text, int len) { if (len>0) *text=0; return 0; }
};

class MenuEntryLabel : public MenuEntry
{
protected:
  const char *label;
public:
  virtual ~MenuEntryLabel() {}
  virtual int MenuText(char*, int);
};
