class MenuEntryFunctionFloatEdit : public MenuEntryLabel
{
  float *tfloat;
protected:
  float lo, hi, step;
  char *format;
  void *fn;
public:
  virtual ~MenuEntryFunctionFloatEdit() {}
  virtual void OnMenuOpen(Menu*, MenuSystem*);
  virtual int MenuText(char*, int);
  virtual void OnButtonPress(int);
  void FixValue();
  virtual void SetValue(float n) { *tfloat = n; }
  virtual float GetValue() { return tfloat ? *tfloat : 0; }
};

int MenuEntryFunctionFloatEdit::MenuText( char *text, int len )
{
	if ( len && label )
	{
		int lused=MenuEntryLabel::MenuText(text,len);
		char tval[32];
		if ( format )
		{
			sprintf(tval,format,GetValue());
		}
		else
		{
			sprintf(tval," : %0.2f",GetValue());
		}

		strncpy(text+lused,tval,len-lused);
		text[len-1]=0;
		return strlen(text);
	}
	else
		return MenuEntry::MenuText(text,len);
}
